-- TPC-DS Test_Query Query 371
-- Based on: query48.tpl (medium)
-- Variation: 10

select sum (ss_quantity) from store_sales, store, customer_demographics, customer_address, date_dim where s_store_sk = ss_store_sk and  ss_sold_date_sk = d_date_sk and d_year = 2010 and ( ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.1' and cd_education_status = 'ES.3' and ss_sales_price between 100.1 and 150.1 ) or ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.1' and cd_education_status = 'ES.1' and ss_sales_price between 50.1 and 100.2 ) or ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.3' and cd_education_status = 'ES.3' and ss_sales_price between 150.1 and 200.1 ) ) and ( ( ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.1', 'STATE.4', 'STATE.4') and ss_net_profit between 1 and 2076 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.4', 'STATE.4', 'STATE.4') and ss_net_profit between 151 and 2998 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.7', 'STATE.9', 'STATE.8') and ss_net_profit between 49 and 25000 ) );
